    T x=338 y=336 w=100 h=54 text=NEXT size=26 font="Barlow Condensed Bold" cspace=3.85 f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
# widget button vbscan {"x":24,"y":402,"w":136,"h":54,"states":[{"label":"RESCAN","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=vbscan {
