    T x=42 y=402 w=100 h=54 text=RESCAN size=26 font="Barlow Condensed Bold" cspace=3.85 f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
# widget button vbback {"x":172,"y":402,"w":136,"h":54,"states":[{"label":"BACK","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=vbback {
    R id=vbback_hit click=1 x=172 y=402 w=136 h=54
    R x=172.5 y=402.5 w=135 h=53 rx=5.5 f=@theme_row s=#5A5A69 sw=1 fo==1-0.25*down
    T x=190 y=402 w=100 h=54 text=BACK size=26 font="Barlow Condensed Bold" cspace=3.85 f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
# widget button vbsave {"x":320,"y":402,"w":136,"h":54,"states":[{"label":"SAVE","variant":"primary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=vbsave {
    R id=vbsave_hit click=1 x=320 y=402 w=136 h=54
    R x=321 y=403 w=134 h=52 rx=5 f=@theme_brand s=#FF772D sw=2 fo==1-0.25*down
    T x=338 y=402 w=100 h=54 text=SAVE size=26 font="Barlow Condensed Bold" cspace=3.85 f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
G v==lt(ver,11118) {
    R x=0 y=0 w=480 h=58 f=#000000CC
    T x=14.4 y=0 w=451.2 h=58 text="Update ScriptedScreens Vector to 0.11.118 or newer" size=26 f=#FFCC00
}
